const sk = (id, empfaenger, fallbackEmpfaenger, text, moderatorGut, moderatorSchlecht, o) => S.push(Object.assign({ id, nr: Number(id.slice(2)), empfaenger, minuteOffset: null, vertraulich: true, text, moderatorGut, moderatorSchlecht, prioritaet: 2, fallbackEmpfaenger }, o || {}));
sk('SK01', 'rz-betrieb', ['leiter-it', 'facility-management'], 'Die USV-Warnung kennst du: Der Temperatursensor meldet seit Wochen sporadisch. Das Sicherheits-Update des Herstellers für die Batteriesteuerung ist seit drei Monaten überfällig, der Wartungstermin wurde zweimal verschoben. Du hast Bereitschaft und entscheidest, ob du heute Nacht noch etwas unternimmst.', 'Gebäudetechnik informiert, Hersteller-Hotline angefragt, Meldung dokumentiert – auch wenn es ein Fehlalarm sein könnte.', 'Quittiert und vergessen, weil der Sensor „sowieso spinnt“.', { minuteOffset: 1, prioritaet: 2 });
sk('SK02', 'facility-management', ['leiter-arbeitssicherheit', 'rz-betrieb'], 'Der Wachdienst ruft dich an: Geruch im Technikflur. Deine Gebäudeleittechnik zeigt für den USV-Raum zusätzlich „Lüftung Störung“. Du bist 40 Minuten entfernt. Die Brandmeldeanlage ist ruhig.', 'Sofort losfahren, IT-Rufbereitschaft informieren, Wachdienst anweisen, nicht allein in den USV-Raum zu gehen.', 'Bis zum Morgen abwarten oder den Wachmann allein nachsehen lassen.', { zuBeginnVon: 'LK02' });
sk('SK03', 'leiter-it', ['rz-betrieb', 'geschaeftsfuehrer-ceo'], 'Die Rufbereitschaft meldet: Serverraum 31 °C, steigend. Die Übertragung der Aktionspreise an die Filialkassen läuft seit 03:00 Uhr und braucht noch etwa 40 Minuten; die Partnermärkte laden gerade ihre Tagesabschlüsse hoch. Herunterfahren heißt: Beides bricht ab – und das kurz vor dem Saisonstart.', 'Abwägung laut aussprechen, Entscheidung treffen und dokumentieren; Gebäudetechnik und Geschäftsführung informieren.', 'Abwarten, ohne zu entscheiden, oder allein entscheiden, ohne dass es jemand erfährt.', { zuBeginnVon: 'LK03', prioritaet: 1 });
sk('SK04', 'schichtleiter-zentrallager', ['leiter-arbeitssicherheit', 'leiterin-personal'], 'Am Sammelplatz fehlt der Kollege aus dem Rechenzentrumsteam, den die Rufbereitschaft zur Unterstützung gerufen hatte. Sein Auto steht auf dem Hof, ans Telefon geht er nicht. Die Feuerwehr fragt dich, ob noch jemand im Gebäude ist.', 'Sofort an die Einsatzleitung melden, Name und letzter bekannter Ort; niemand geht selbst suchen.', 'Selbst ins Gebäude gehen oder die Information erst nach eigener Suche weitergeben.', { zuBeginnVon: 'LK05', prioritaet: 1 });
sk('SK05', 'leiterin-personal', ['geschaeftsfuehrer-ceo', 'leiter-arbeitssicherheit'], 'Entwarnung: Der Kollege aus dem Rechenzentrumsteam ist wohlauf. Er hatte das Gebäude über den Hinterausgang verlassen und stand am falschen Sammelplatz an Tor 2. Seine Frau hat inzwischen dreimal in der Zentrale angerufen – die Telefonanlage ist tot, sie hat nur die Bandansage gehört.', 'Angehörige zurückrufen, Sammelplatzregelung festhalten, Nachbereitung des Vorfalls ansetzen.', 'Angehörige vergessen, weil „ja alles gut ausgegangen ist“.', { minuteOffset: 15 });
sk('SK06', 'leiter-arbeitssicherheit', ['facility-management', 'geschaeftsfuehrer-ceo'], 'Der Einsatzleiter weist dich darauf hin: Bei brennenden Lithium-Ionen-Batterien können Fluorwasserstoff und andere ätzende Gase entstehen. Er empfiehlt, USV-Raum und Serverraum erst nach Messung und Freigabe durch Sachverständige zu betreten – ausdrücklich auch für IT-Personal.', 'Betretungsverbot klar festlegen und allen Bereichen mitteilen, Messung beauftragen.', 'Die Empfehlung bleibt bei dir, die IT plant schon das Betreten.', { zuBeginnVon: 'LK06', prioritaet: 1 });
sk('SK07', 'informationssicherheit', ['leiter-it', 'notfallmanagement-bcm'], 'Weil die Anmeldedienste der Zentrale ausgefallen sind, teilen Beschäftigte Zugangsdaten im Chat und nutzen private Hotspots. Ein Filialleiter fragt, ob er die Kundenliste der Gewerbekunden als Tabelle an seine private Mailadresse schicken darf, um telefonisch nachfassen zu können.', 'Klare Regel für Behelfslösungen ausgeben (was erlaubt ist, was nicht, wer genehmigt); Datenschutzfrage fachlich prüfen lassen statt Einzelfall durchwinken.', 'Alles erlauben, „weil Notfall ist“, oder alles verbieten, ohne Alternative.', { zuBeginnVon: 'LK07' });
sk('SK08', 'it-support-filialen', ['leiter-it', 'regionalleiterin-filialen-nord'], 'Die Herstellerdokumentation der Kassen sagt: Im Offline-Betrieb speichern sie Abverkäufe etwa 72 Stunden, danach verweigern sie neue Buchungen, bis sie wieder mit der Zentrale synchronisiert sind. Das wäre Freitag gegen 03:00 Uhr. In den Filialen weiß das noch niemand.', 'Die Frist sofort an den Krisenstab geben – sie bestimmt die Wiederanlaufplanung.', 'Die Frist für sich behalten, „bis dahin läuft es ja wieder“.', { minuteOffset: 21.5, prioritaet: 1 });
sk('SK09', 'regionalleiterin-filialen-nord', ['regionalleiter-filialen-sued', 'geschaeftsfuehrer-ceo'], 'Zwei Filialleitungen fragen, ob sie heute öffnen sollen. Eine Filiale hat schon handgeschriebene Schilder aufgehängt: „Aktionspreise gelten ab Donnerstag“ – niemand hat das entschieden.', 'Einheitliche Entscheidung einfordern und an alle Filialen geben; eigenmächtige Zusagen stoppen.', 'Jede Filiale entscheiden lassen.', { zuBeginnVon: 'LK08' });
sk('SK10', 'regionalleiter-filialen-sued', ['regionalleiterin-filialen-nord', 'geschaeftsfuehrer-ceo'], 'Zwei Filialleitungen deiner Region wollen es unterschiedlich machen: Eine will den Prospektpreis per Handeingabe geben, die Nachbarfiliale will ihn verweigern. In einer Facebook-Gruppe fragen Kundinnen schon, welche Filiale den Preis gewährt.', 'Den Widerspruch sofort in den Krisenstab tragen und eine einheitliche Regel verlangen.', 'Die eigene Region regeln, ohne die andere Region und den Krisenstab einzubinden.', { minuteOffset: 27 });
sk('SK11', 'partnerbetreuung', ['leiter-finanzen-cfo', 'geschaeftsfuehrer-ceo'], 'Drei Partner haben dich schon angerufen. Einer liest dir aus dem Servicevertrag vor: Wiederherstellungsziel 24 Stunden für Kassen- und Preisdienste. Er will bis 12 Uhr wissen, wann es weitergeht, sonst wendet er sich an den Verbundvorstand.', 'Die Frist und die Stimmung in den Krisenstab tragen und eine abgestimmte Botschaft mit Termin holen.', 'Den Partnern auf eigene Faust einen Termin nennen.', { zuBeginnVon: 'LK09', prioritaet: 1 });
sk('SK12', 'leiter-finanzen-cfo', ['geschaeftsfuehrer-ceo', 'partnerbetreuung'], 'Im Servicevertrag mit den Partnermärkten stehen Gutschriften bei Überschreiten des Wiederherstellungsziels (Szenarioannahme: 2.000 € je Markt und angefangenem Tag). Zwei Verträge enthalten zusätzlich ein Sonderkündigungsrecht bei „erheblicher Störung“. Ob dieser Fall eintritt, ist fachlich zu prüfen.', 'Vertragsrisiko beziffern, fachliche Prüfung anstoßen, Geschäftsführung informieren.', 'Vertragsfolgen herunterspielen oder als sicher behaupten.', { minuteOffset: 30.5 });
sk('SK13', 'facility-management', ['leiter-arbeitssicherheit', 'leiter-it'], 'Der Sachverständige: Reinigung des Serverraums durch eine Fachfirma dauert fünf bis acht Arbeitstage. Die Klimaanlage darf bis zur Prüfung nicht laufen – Feuchtigkeit plus Ruß beschleunigt die Korrosion. Ob die Hardware danach noch zuverlässig ist, kann er nicht sagen.', 'Zeitrahmen und Unsicherheit offen in den Krisenstab geben; Freigabeprozess festlegen.', 'Einen Wiederinbetriebnahmetermin versprechen.', { minuteOffset: 33.5, prioritaet: 1 });
sk('SK14', 'rz-betrieb', ['leiter-it'], 'Über die Kamera der Gebäudetechnik siehst du in den Serverraum: Die Racks stehen, überall Rußfilm. In Rack 7 steht der Backup-Server mit der Dienstagssicherung von 01:00 Uhr. Wird er bald geborgen und gereinigt, sind die Daten vermutlich lesbar – je länger er im Ruß steht, desto größer die Korrosionsgefahr.', 'Die Information mit Unsicherheit an die IT-Leitung und den Krisenstab geben; nicht selbst hineingehen.', 'Eine eigene „schnelle Bergung“ planen.', { minuteOffset: 35, prioritaet: 1 });
sk('SK15', 'leiterin-kommunikation-pr', ['geschaeftsfuehrer-ceo'], 'Ein Lokaljournalist hat ein Foto: Feuerwehr vor dem Verwaltungsgebäude, Rauch aus einem Lüftungsgitter. Auf Facebook schreibt jemand von „Akkubrand, giftige Gase, Anwohner sollen Fenster schließen“. Die Feuerwehr hat bisher nur „Brand in einem Technikraum“ bestätigt.', 'Nur Bestätigtes sagen, für Gesundheitsfragen auf Feuerwehr und Behörden verweisen, Hotline briefen.', 'Gerüchte dementieren, ohne es zu wissen.', { zuBeginnVon: 'LK11' });
sk('SK16', 'leiterin-logistik-zentrallager', ['schichtleiter-zentrallager', 'geschaeftsfuehrer-ceo'], 'Ohne Lagerverwaltung kennt niemand die Lagerplätze von rund 40.000 Artikeln. Ein Spediteur wartet seit 06:00 Uhr auf Ladung und berechnet ab Mittag Standgeld. Die Filialen rufen einzeln an und bestellen „das Wichtigste“.', 'Bestellungen bündeln, Prioritäten mit dem Krisenstab festlegen, Papierbetrieb so organisieren, dass er nachgebucht werden kann.', 'Wer zuerst anruft, bekommt zuerst.', { zuBeginnVon: 'LK12', prioritaet: 1 });
sk('SK17', 'schichtleiter-zentrallager', ['leiterin-logistik-zentrallager'], 'Die Kommissionierer der Frühschicht sagen: „Wir kennen das Lager, wir machen das auf Zuruf.“ Fehllieferungen wären wahrscheinlich, aber die Filialen hätten Ware zum Saisonstart.', 'Vorschlag mit Risiko an die Lagerleitung geben; Papierbelege für jede Entnahme verlangen.', 'Ohne Belege loslegen.', { minuteOffset: 43 });
sk('SK18', 'leiter-einkauf', ['leiter-finanzen-cfo', 'leiter-it'], 'Der Serverhändler bietet zwei Rahmen in drei Tagen gegen 35 % Aufschlag. Der Colocation-Anbieter kann das Ausweich-Rack binnen 48 Stunden erweitern – Mindestlaufzeit zwölf Monate, Kosten für das erste Jahr rund 210.000 € einschließlich Dienstleistern (Szenarioannahme).', 'Angebote vergleichbar machen und dem Krisenstab zur Entscheidung vorlegen; Fristen der Angebote nennen.', 'Allein bestellen oder Angebote verfallen lassen.', { minuteOffset: 45.5, prioritaet: 1 });
sk('SK19', 'leiter-it', ['rz-betrieb', 'geschaeftsfuehrer-ceo'], 'Dein Team rechnet: Im Ausweich-Rack reicht die Leistung für Kassen- und Preisdienste und den Kern der Warenwirtschaft. Die Netzwerkanbindung der 23 Märkte muss neu eingerichtet werden – das wurde nie vollständig geübt. Zwei deiner fünf Leute sind seit Dienstag 03:00 Uhr wach.', 'Realistisches Lagebild mit Personalengpass an den Krisenstab; Ruhezeiten einplanen.', 'Zu optimistische Zusagen, um Druck abzubauen.', { minuteOffset: 47, prioritaet: 1 });
sk('SK20', 'geschaeftsfuehrer-ceo', ['partnerbetreuung', 'leiter-finanzen-cfo'], 'Der Vorsitzende des Verbundbeirats ruft dich vor der Videokonferenz privat an: Zwei Partner wollen den IT-Servicevertrag kündigen. Er erwartet eine klare Aussage, wann ihre Kassen wieder voll laufen – und ob Waterkant die eigenen Märkte bevorzugt. „Ich will nicht hören, dass Sie es nicht wissen.“', 'Ruhig bleiben, ehrliche Spanne, keine Zusage zur Reihenfolge, die nicht entschieden ist; Druck in den Krisenstab tragen.', 'Eine Zusage machen, die den Krisenstab bindet, ohne dass er es weiß.', { zuBeginnVon: 'LK18', prioritaet: 1 });
sk('SK21', 'leiter-arbeitssicherheit', ['facility-management', 'geschaeftsfuehrer-ceo'], 'Für eine Bergung aus dem Serverraum vor der Freigabe brauchst du: Gefährdungsbeurteilung, aktuelles Messergebnis, Fachfirma mit Schutzausrüstung, Freiwilligkeit, Dokumentation. Die Fachfirma könnte heute um 14 Uhr – mit eigenem Personal, nicht mit eurer IT.', 'Voraussetzungen klar benennen; entscheiden lässt du dir nicht abnehmen, aber auch nicht aufdrängen.', 'Aus Zeitdruck zustimmen, ohne Voraussetzungen zu prüfen – oder pauschal ablehnen, ohne zu begründen.', { zuBeginnVon: 'LK14', prioritaet: 1 });
sk('SK22', 'informationssicherheit', ['leiter-it', 'leiter-finanzen-cfo'], 'Wenn die Warenwirtschaft ins Ausweich-Rack zieht, laufen dort auch Daten der Gewerbekunden und Partnermärkte. Der Vertrag mit dem Colocation-Anbieter beschreibt nur die Lagerung von Sicherungskopien, nicht den Produktivbetrieb. Was das bedeutet, ist fachlich zu prüfen.', 'Thema in den Krisenstab, fachliche Prüfung parallel anstoßen, ohne den Wiederanlauf zu blockieren.', 'Schweigen oder den Wiederanlauf allein stoppen.', { zuBeginnVon: 'LK15' });
sk('SK23', 'online-shop-leitung', ['leiter-it', 'leiterin-kommunikation-pr'], 'Der Shop zeigt seit Dienstag Bestände von Montagnacht. 312 Bestellungen „Abholung in der Filiale“ sind eingegangen, ein Teil für Artikel, die vermutlich nicht da sind. Der Hoster könnte den Shop auf „nur Information“ schalten.', 'Entscheidung über den Shop in den Krisenstab, Kundinnen und Kunden aktiv informieren.', 'Den Shop laufen lassen und hoffen.', { minuteOffset: 55 });
sk('SK24', 'kundenservice-hotline', ['leiterin-kommunikation-pr', 'regionalleiterin-filialen-nord'], 'Seit gestern über 600 Anrufe. Die häufigste Frage: „Gilt der Prospektpreis – und bekomme ich die Differenz zurück?“ Die bisherige Sprachregelung beantwortet das nicht. Mehrere Anrufer drohen mit einer Beschwerde wegen irreführender Werbung.', 'Sprachregelung einfordern und die Lage mit Zahlen an den Krisenstab geben.', 'Jede Kollegin antwortet nach eigenem Ermessen.', { minuteOffset: 61.5, prioritaet: 1 });
sk('SK25', 'leiterin-kommunikation-pr', ['geschaeftsfuehrer-ceo', 'kundenservice-hotline'], 'Ein bekannter Heimwerker-Kanal hat ein Video aus einer Filiale gepostet: Der Bon zeigt den alten Preis, daneben der Prospekt. 80.000 Aufrufe innerhalb weniger Stunden.', 'Einheitliche Kulanzregel öffentlich machen, Fehler einräumen, ohne rechtlich zu bewerten.', 'Löschen lassen wollen oder den Kanal angreifen.', { minuteOffset: 62.5 });
sk('SK26', 'partnerbetreuung', ['geschaeftsfuehrer-ceo'], 'Ein Partnermarkt hat eigenständig einen anderen Kassenanbieter angefragt und will dir heute sagen, ob er „vorerst selbst etwas aufbaut“. Damit würde er aus dem gemeinsamen Preis- und Warenwirtschaftssystem ausscheren.', 'Verständnis zeigen, Lage ehrlich darstellen, Entscheidung der Geschäftsführung einholen.', 'Den Partner unter Druck setzen oder ihn kommentarlos ziehen lassen.', { minuteOffset: 66 });
sk('SK27', 'leiter-finanzen-cfo', ['geschaeftsfuehrer-ceo', 'facility-management'], 'Der Versicherungsmakler weist darauf hin: In den Bedingungen der Elektronikversicherung gibt es Regelungen zu Wartungsauflagen. Die USV-Wartung war überfällig. Ob und wie stark das die Erstattung beeinflusst, kann nur die fachliche Prüfung des Vertrags klären.', 'Risiko in die Liquiditätsplanung aufnehmen und offen in den Krisenstab geben.', 'Mit der vollen Erstattung planen.', { zuBeginnVon: 'LK24', prioritaet: 1 });
sk('SK28', 'it-support-filialen', ['leiter-it', 'rz-betrieb'], 'Bei vier Filialen schlägt der Kassenabgleich fehl: Die Abverkäufe von Dienstag bis Donnerstag liegen nur auf den Kassen selbst. Wenn ihr die Kassen neu aufsetzt, sind die Daten weg.', 'Abgleich stoppen, Daten sichern lassen, Krisenstab informieren.', 'Neu aufsetzen, damit es schnell geht.', { zuBeginnVon: 'LK22' });
sk('SK29', 'rz-betrieb', ['leiter-it', 'informationssicherheit'], 'Die Rücksicherung läuft sauber. Die Aktionspreise fehlen in der Montagskopie; der Einkauf hat sie nur als PDF vom Druckdienstleister. Abtippen dauert, Einlesen per Skript aus dem PDF ist schnell, aber ungeprüft.', 'Vier-Augen-Prüfung für jeden Preisimport festlegen und Freigabe einholen.', 'Ungeprüftes Einlesen, „weil die Kassen heute Abend laufen müssen“.', { zuBeginnVon: 'LK19' });
sk('SK30', 'leiter-einkauf', ['leiterin-logistik-zentrallager', 'leiter-finanzen-cfo'], 'Lieferanten fragen nach Bestellungen von Montag, die im System fehlen. Zwei haben „vorsichtshalber“ doppelt geliefert, einer hat gar nicht geliefert, weil keine Bestätigung kam.', 'Bestellungen aus Lieferantenbestätigungen rekonstruieren, Abgleich organisieren, Krisenstab informieren.', 'Alles annehmen, was kommt, und später sortieren.', { zuBeginnVon: 'LK23' });
sk('SK31', 'leiterin-logistik-zentrallager', ['schichtleiter-zentrallager', 'leiter-einkauf'], 'Die Wareneingänge vom Montag (38 Lkw) sind im System nicht gebucht. Die Ware steht im Lager, laut System gibt es sie nicht – die Filialen sehen „nicht verfügbar“.', 'Nachbuchung priorisieren (schnelldrehende Saisonware zuerst) und Datenstand erst danach freigeben.', 'Bestände schätzen und freigeben.', { minuteOffset: 86 });
sk('SK32', 'leiterin-personal', ['geschaeftsfuehrer-ceo', 'leiter-it'], 'Drei Kolleginnen und Kollegen der IT haben seit Dienstag über 70 Stunden gearbeitet, teils in Doppelschichten, zwei Filialleitungen sind krank. Der Betriebsrat fragt, wer die Einsätze am Wochenende angeordnet hat. Arbeitszeitfragen sind fachlich zu prüfen.', 'Ruhezeiten organisieren, Vertretungen planen, Betriebsrat einbinden.', 'Weitermachen wie bisher, „es ist ja bald vorbei“.', { zuBeginnVon: 'LK27', prioritaet: 1 });
sk('SK33', 'kundenservice-hotline', ['online-shop-leitung'], 'Kundinnen und Kunden fragen, ob ihre Online-Abholungen vom Dienstag noch gelten und ob sie den Prospektpreis nachträglich erstattet bekommen.', 'Sprachregelung für Abholungen und Erstattungen einfordern.', 'Einzelfallzusagen ohne Regel.', { zuBeginnVon: 'LK25' });
sk('SK34', 'assistenz-gf-dokumentation', ['notfallmanagement-bcm', 'geschaeftsfuehrer-ceo'], 'Die Entscheidungen der Brandnacht sind nirgends dokumentiert: wer wann was abgeschaltet, wen informiert, wem welche Anweisung gegeben hat. Versicherer und Sachverständige werden danach fragen.', 'Chronologie jetzt aus Telefonlisten, Chats und Erinnerungen rekonstruieren und ab sofort mitschreiben.', 'Erst am Ende aufschreiben.', { zuBeginnVon: 'LK06' });
sk('SK35', 'notfallmanagement-bcm', ['leiter-it', 'geschaeftsfuehrer-ceo'], 'Das IT-Notfallhandbuch liegt als Datei auf dem Fileserver im gesperrten Serverraum. Eine Papierkopie gibt es im Tresor der Geschäftsführung – im Verwaltungsgebäude, das bis zur Freigabe gesperrt ist.', 'Lücke offen benennen, Kopie aus der Cloud oder von Einzelpersonen beschaffen, Krisenstab nach Erfahrung und Checkliste arbeiten lassen.', 'So tun, als gäbe es einen Plan.', { minuteOffset: 21.5, prioritaet: 1 });
sk('SK36', 'facility-management', ['leiter-it', 'geschaeftsfuehrer-ceo'], 'Der Sachverständige fragt dich, wer für die USV-Wartung zuständig war: Gebäudetechnik, weil es Haustechnik ist, oder IT, weil sie im Rechenzentrum steht. In den Unterlagen ist es nicht eindeutig geregelt.', 'Lücke ehrlich benennen und als Maßnahme festhalten.', 'Die Verantwortung der jeweils anderen Abteilung zuschieben.', { zuBeginnVon: 'LK26' });
sk('SK37', 'leiter-it', ['geschaeftsfuehrer-ceo', 'leiter-finanzen-cfo'], 'Die Geschäftsführung will bis Mittwoch deine Empfehlung: zurück ins eigene Rechenzentrum, dauerhaft auslagern oder zwei Standorte. Dein Team ist erschöpft, die Partnermärkte wollen Gewissheit.', 'Kriterien statt Bauchgefühl: Risiko, Kosten, Zeit, Personal; Entscheidung erst nach Prüfung.', 'Unter Druck aus dem Bauch entscheiden.', { zuBeginnVon: 'LK28' });
sk('SK38', 'regionalleiterin-filialen-nord', ['regionalleiter-filialen-sued'], 'Die Kassen laufen wieder, aber Rückgaben von Bons aus dem Offline-Zeitraum lassen sich nicht stornieren. Kundinnen und Kunden stehen mit Ware und Bon an der Information.', 'Übergangsregel für Rückgaben einfordern und kommunizieren.', 'Jede Filiale improvisiert.', { minuteOffset: 83 });
sk('SK39', 'online-shop-leitung', ['leiterin-kommunikation-pr'], 'Für Samstag erwartet der Shop-Hoster das Dreifache der üblichen Besucherzahl. Jeder Preis- oder Bestandsfehler wird heute tausendfach gesehen.', 'Nur freigegebene Daten zeigen, Aussagen zu Verfügbarkeit vorsichtig formulieren.', 'Alles freischalten, was technisch geht.', { minuteOffset: 92 });
sk('SK40', 'informationssicherheit', ['leiter-it', 'rz-betrieb'], 'Das Team will für die Umstellung der 23 Märkte die Firewall des Ausweich-Racks „vorübergehend für alles öffnen“, damit es schneller geht. Später zu schließen ist geplant, aber nicht terminiert.', 'Keine pauschale Öffnung; Regeln je Markt mit Vier-Augen-Prüfung; Ausnahme nur mit Befristung und Freigabe.', 'Zustimmen, weil der Druck groß ist.', { minuteOffset: 70 });
// Folgekarten aus Entscheidungen
sk('SK41', 'rz-betrieb', ['leiter-it'], 'Der Sanierer hat die Kamerabilder ausgewertet: Die Geräte, die bis zum Stromausfall liefen, haben Ruß in die Gehäuse gezogen. Mehr Hardware muss ersetzt werden, und der Backup-Server ist innen stärker verschmutzt als gedacht – eine Bergung wäre aufwendiger, die Daten darauf schwerer zu retten.', 'Mehrbedarf an Ersatzhardware offen in den Krisenstab geben und in die Entscheidung über die Bergung einbeziehen.', 'Für sich behalten, weil die Entscheidung in der Brandnacht schon gefallen ist.', { nurNachWeiche: true, prioritaet: 1 });
sk('SK42', 'geschaeftsfuehrer-ceo', ['partnerbetreuung'], 'Der Verbundvorstand ruft an: Die Partner haben aus der Lokalzeitung mehr über den Brand erfahren als von Waterkant. Er verlangt bis heute Abend ein Gespräch mit dir.', 'Sofort Termin anbieten, Versäumnis einräumen, festen Informationstakt zusagen.', 'Rechtfertigen statt informieren.', { nurNachWeiche: true, prioritaet: 1 });
sk('SK43', 'leiter-arbeitssicherheit', ['facility-management'], 'Die Berufsgenossenschaft fragt nach der Gefährdungsbeurteilung für den Einsatz der Fachfirma im kontaminierten Serverraum und nach dem Messprotokoll.', 'Unterlagen liegen vor und werden geliefert.', 'Es gibt keine schriftliche Grundlage.', { nurNachWeiche: true });
sk('SK44', 'partnerbetreuung', ['geschaeftsfuehrer-ceo'], 'Drei Partnermärkte konnten am Freitagmorgen stundenlang nicht kassieren, während alle Waterkant-Filialen liefen. Einer hat inzwischen Kontakt zu einem anderen IT-Dienstleister aufgenommen und will am Montag ein Gespräch.', 'Reihenfolge und Kriterium offen erklären, Gespräch auf Leitungsebene anbieten.', 'Abstreiten oder kleinreden.', { nurNachWeiche: true, prioritaet: 1 });
sk('SK45', 'online-shop-leitung', ['leiter-it'], 'Nach der schnellen Verlagerung zeigt der Online-Shop für 140 Artikel noch Preise von Montag – der Abgleich der Aktionspreise fehlt in der neuen Umgebung.', 'Betroffene Artikel sofort aus dem Verkauf nehmen und Abgleich nachholen.', 'Weiterverkaufen und später korrigieren.', { nurNachWeiche: true });
sk('SK46', 'geschaeftsfuehrer-ceo', ['leiter-finanzen-cfo'], 'Der Vorsitzende der Gesellschafterversammlung hat von der möglichen Erweiterung des Ausweich-Racks gehört und ruft dich an. Nach eurer Geschäftsordnung brauchen Verträge mit einer Bindung von zwölf Monaten oder länger die Zustimmung der Gesellschafter. Er ist bis Freitag im Ausland, aber telefonisch erreichbar: „Entscheiden Sie, was nötig ist – aber ich will es vorher wissen und nicht aus der Rechnung erfahren.“', 'Beide Wege mit Kosten und Folgen kurz darstellen, Zustimmung einholen und dokumentieren, bevor unterschrieben wird.', 'Ohne Zustimmung unterschreiben – oder die Entscheidung bis Freitag liegen lassen.', { zuBeginnVon: 'LK15', minuteOffset: 53.5, prioritaet: 1 });

// Zeitpunkt fuer Karten, die zu Beginn einer Lage kommen: knapp nach deren Minute
S.forEach(k => { if (k.zuBeginnVon && (k.minuteOffset === null || k.minuteOffset === undefined)) k.minuteOffset = L.find(l => l.id === k.zuBeginnVon).minuteOffset + 0.5; });
// Stationen des Spannungsbogens zeitlich aufsteigend
const AKT_NACH_LK = { vorboten: [1, 3], ausbruch: [4, 7], eskalation: [8, 13], hoehepunkt: [14, 18], folgen: [19, 21], wiederanlauf: [22, 28] };
L.forEach(l => { for (const [akt, [a, b]] of Object.entries(AKT_NACH_LK)) if (l.nr >= a && l.nr <= b) l.akt = akt; });

